    if (tail === 'thin') s += tube([[78, 56], [90, 50], [98, 60], [96, 72]], 2.6, tc, { ow: 0.8 });
    if (tail === 'thick') s += tube([[78, 56], [92, 54], [98, 66]], 5, tc, { ow: 1 });
    if (tail === 'puff') s += ball(84, 50, 6, '#ffffff', { oc: oc(c) });
    if (tail === 'curl') s += line('M80 50 q10 -6 8 4 q-2 8 6 4', oc(c), 2.4);
    if (tail === 'up') s += tube([[78, 52], [88, 40], [92, 30]], 5, c);
    for (let k = 0; k < legs; k++) s += tube([[40 + k * 12, 66], [38 + k * 12, 80]], 6, D(c, k % 2 ? 0.12 : 0));
    s += ell(56, 58, bw, bh, c) + ell(hx + 10, hy + 6, hr * 1.1, hr * 0.9, c);
    if (ear === 'round') s += ball(hx + 16, hy - 6, 7, ec, { oc: oc(c) });
    if (ear === 'long') s += ell(hx + 18, hy - 16, 4.5, 15, ec, 10, { oc: oc(c) }) + ell(hx + 10, hy - 16, 4.5, 15, ec, -8, { oc: oc(c) });
