    if (ear === 'horn') s += line(`M${hx + 14} ${hy - 4} q-2 -8 4 -10 M${hx + 20} ${hy - 4} q4 -8 8 -6`, '#e0d6c2', 3);
    if (snout === 'pig') s += ell(hx, hy + 8, 4, 6, L(c, 0.2)) + ball(hx - 0.6, hy + 6.6, 0.9, oc(c), { w: 0 }) + ball(hx - 0.6, hy + 9.6, 0.9, oc(c), { w: 0 });
